package com.bank.spark.model;

// Simulated Spark UI stage metrics for a join side.
public class StageMetrics {
    private final String side;
    private final long shuffleReadBytes;
    private final long shuffleWriteBytes;

    public StageMetrics(String side, long shuffleReadBytes, long shuffleWriteBytes) {
        this.side = side;
        this.shuffleReadBytes = shuffleReadBytes;
        this.shuffleWriteBytes = shuffleWriteBytes;
    }

    public String getSide() { return side; }
    public long getShuffleReadBytes() { return shuffleReadBytes; }
    public long getShuffleWriteBytes() { return shuffleWriteBytes; }
    public boolean hasShuffle() { return shuffleReadBytes > 0 || shuffleWriteBytes > 0; }
}
