package com.bank.spark.service;

import com.bank.spark.model.StageMetrics;

// Verifies a broadcast join from the plan text and UI metrics.
public class JoinPlanVerifier {

    // Plan evidence: broadcast if plan mentions both markers and NOT SortMergeJoin.
    public boolean planShowsBroadcast(String formattedPlan) {
        boolean hasBroadcastExchange = formattedPlan.contains("BroadcastExchange");
        boolean hasBroadcastHashJoin = formattedPlan.contains("BroadcastHashJoin");
        boolean hasSortMerge = formattedPlan.contains("SortMergeJoin");
        return hasBroadcastExchange && hasBroadcastHashJoin && !hasSortMerge;
    }

    // UI evidence: the large side must have NO shuffle.
    public boolean uiConfirmsNoLargeSideShuffle(StageMetrics largeSide) {
        return !largeSide.hasShuffle();
    }

    public String verdict(String plan, StageMetrics largeSide) {
        boolean planOk = planShowsBroadcast(plan);
        boolean uiOk = uiConfirmsNoLargeSideShuffle(largeSide);
        if (planOk && uiOk) return "VERIFIED broadcast join: plan + UI both confirm";
        if (planOk) return "Plan says broadcast but UI shows large-side shuffle — investigate AQE / wrong stage";
        return "NOT a broadcast join: plan shows SortMergeJoin or missing BroadcastExchange";
    }
}
