package com.bank.spark;

import com.bank.spark.model.StageMetrics;
import com.bank.spark.service.JoinPlanVerifier;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class JoinVerifyDemo {

    private static final Logger log = Logger.getLogger(JoinVerifyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JoinPlanVerifier verifier = new JoinPlanVerifier();

        // Case 1: a genuine broadcast join plan + no large-side shuffle.
        String broadcastPlan = ""
                + "*(2) BroadcastHashJoin [branchId], [branchId], Inner, BuildRight\n"
                + ":- *(2) FileScan parquet transactions[...]\n"
                + "+- BroadcastExchange HashedRelationBroadcastMode, [id=#42]\n"
                + "   +- *(1) FileScan parquet branches[...]";
        StageMetrics largeNoShuffle = new StageMetrics("transactions", 0, 0);
        log.info("Case 1 (hinted join): " + verifier.verdict(broadcastPlan, largeNoShuffle));

        // Case 2: a sort-merge join plan + large shuffle on both sides.
        String sortMergePlan = ""
                + "*(5) SortMergeJoin [accountId], [accountId], Inner\n"
                + ":- *(2) Sort [accountId ASC], false\n"
                + ":  +- Exchange hashpartitioning(accountId, 200)\n"
                + "+- *(4) Sort [accountId ASC], false\n"
                + "   +- Exchange hashpartitioning(accountId, 200)";
        StageMetrics largeWithShuffle = new StageMetrics("transactions", 4_000_000_000L, 4_000_000_000L);
        log.warning("Case 2 (expected broadcast but got): " + verifier.verdict(sortMergePlan, largeWithShuffle));

        log.info("Note: with AQE on, trust the Spark UI's FINAL plan over the static explain output.");
    }
}

